// Writes supabase/seed.sql from the demo data in src/lib/demo-data.ts.
// Run with: npm run seed:sql
import { writeFileSync } from "node:fs";
import { chunkDocument } from "../src/lib/chunk.ts";
import { DEMO_BUSINESS, DEMO_DOCUMENTS, DEMO_TEST_CASES } from "../src/lib/demo-data.ts";

const q = (value: string) => `'${value.replace(/'/g, "''")}'`;
const list = (values: string[]) => `array[${values.map(q).join(", ")}]::text[]`;
const b = DEMO_BUSINESS;

const lines: string[] = [
  "-- Demo business for Askwell. Generated by scripts/make-seed.ts; do not edit by hand.",
  "-- Safe to run again: it replaces the demo's documents and tests and keeps its conversations.",
  "",
  "insert into public.businesses (id, owner_id, slug, name, assistant_name, greeting, tone, daily_limit, is_demo, suggestions)",
  `values (${q(b.id)}, null, ${q(b.slug)}, ${q(b.name)}, ${q(b.assistantName)}, ${q(b.greeting)}, ${q(b.tone)}, ${b.dailyLimit}, true, ${list(b.suggestions)})`,
  "on conflict (id) do update set name = excluded.name, assistant_name = excluded.assistant_name,",
  "  greeting = excluded.greeting, tone = excluded.tone, daily_limit = excluded.daily_limit, suggestions = excluded.suggestions;",
  "",
  `delete from public.documents where business_id = ${q(b.id)};`,
  `delete from public.test_cases where business_id = ${q(b.id)};`,
  "",
];

for (const doc of DEMO_DOCUMENTS) {
  const chunks = chunkDocument(doc.content);
  lines.push(
    "with doc as (",
    "  insert into public.documents (business_id, title, source_type, content, passage_count)",
    `  values (${q(b.id)}, ${q(doc.title)}, 'text', ${q(doc.content)}, ${chunks.length})`,
    "  returning id",
    ")",
    "insert into public.passages (business_id, document_id, document_title, heading, position, content)",
    `select ${q(b.id)}, doc.id, ${q(doc.title)}, v.heading, v.position, v.content from doc, (values`,
    chunks.map((c) => `  (${c.heading ? q(c.heading) : "null"}, ${c.position}, ${q(c.content)})`).join(",\n"),
    ") as v (heading, position, content);",
    "",
  );
}

lines.push(
  "insert into public.test_cases (business_id, question, expected, key_facts, should_answer, created_at) values",
  DEMO_TEST_CASES.map(
    (t, i) =>
      `  (${q(b.id)}, ${q(t.question)}, ${q(t.expected)}, ${list(t.keyFacts)}, ${t.shouldAnswer}, now() + interval '${i} milliseconds')`,
  ).join(",\n") + ";",
  "",
);

writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log(`Wrote supabase/seed.sql (${DEMO_DOCUMENTS.length} documents, ${DEMO_TEST_CASES.length} tests).`);
